import ast
import json
import sys
import textwrap
from pathlib import Path

edits = json.loads(Path(sys.argv[1]).read_text())["edits"]
assert edits and len({edit["name"] for edit in edits}) == len(edits)
files = {p: p.read_text() for p in Path(".").glob("*.py")}
locations = {}
for path, source in files.items():
    for fn in ast.parse(source).body:
        if isinstance(fn, ast.FunctionDef):
            assert fn.name not in locations
            locations[fn.name] = (path, fn.body[0].lineno - 1, fn.end_lineno)
changes = {p: [] for p in files}
for edit in edits:
    path, start, end = locations[edit["name"]]
    body = textwrap.dedent(edit["body"]).strip("\n")
    assert body.strip()
    changes[path].append((start, end, textwrap.indent(body, "    ") + "\n"))
for path, patches in changes.items():
    if patches:
        lines = files[path].splitlines(keepends=True)
        for start, end, new in sorted(patches, reverse=True):
            lines[start:end] = [new]
        new_source = "".join(lines)
        compile(new_source, str(path), "exec")
        path.write_text(new_source)
